contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving the contract
    // params:
    //  sendAmount - amount of wei to send when calling play (should match ticket)
    //  initialBankBalance - we don't set balances directly; require this contract has enough balance
    // We will call play once and then assert that if the player's address received the payout then c.pot() == 0.
    // We observe payout by checking address(c).balance decreased appropriately vs this contract's balance increase.

    function runTest(uint sendAmount) public payable {
        // require caller provided enough balance to pay the ticket
        require(msg.value == sendAmount);
        // record balances before
        uint beforePlayerBal = address(this).balance - msg.value; // since msg.value already included in this contract's balance
        uint beforeContractBal = address(c).balance;

        // call play forwarding the payment
        c.play{value: msg.value}();

        // record balances after
        uint afterPlayerBal = address(this).balance;
        uint afterContractBal = address(c).balance;

        // Determine whether a payout to the player occurred by detecting an increase in this contract's balance
        // A payout to player would increase this contract balance by (pot_before + msg.value - FEE) which is > msg.value
        // For generality, we detect any net positive change beyond not receiving the ticket back: afterPlayerBal > beforePlayerBal

        bool playerReceivedPayout = afterPlayerBal > beforePlayerBal;

        // The property: if the player received a payout then the pot in c must be zero; conversely, if the player did not receive a payout, pot must be > 0.
        // This single assert encodes equivalence: (playerReceivedPayout) == (c.pot() == 0)
        assert(playerReceivedPayout == (c.pot() == 0));
    }

    // allow the test contract to receive refunds/payouts
    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool __obsd;
    uint __snap;

    constructor(C _c) { c = _c; }

    // amount is the Ether sent as the ticket; caller must fund this test contract beforehand
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // ensure we send the exact ticket amount expected by the original contract
        c.play{value: amount}();   // boundary: the difference is observable after this call
        // after invoking play, during any payout the original contract will call payable(msg.sender).transfer
        // which will trigger this contract's receive(). In receive() we snapshot c.pot() once.
        // Now assert that if we observed the payout take place (i.e., our balance increased by > 0), then
        // the mid-call snapshot of pot was 0. We test the general rule: whenever the player is paid out,
        // pot observed during the payout call must be zero.
        // Note: __obsd indicates whether receive() ran and captured a snapshot.
        assert(!__obsd || __snap == 0);
    }

    receive() external payable {
        // capture the pot value from c during the payout invocation exactly once
        if (!__obsd) {
            __obsd = true;
            __snap = c.pot();
        }
    }
}

