contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter is the block timestamp — the contract's randomness depends only on
    // block.timestamp and block.difficulty, so by fuzzing timestamp we let the fuzzer
    // find values that make the parity 0 (payout in reference) while the mutant pays on 1.
    function testFuzz_property(uint256 ts) public {
        // keep timestamp in a reasonable range but wide: non-zero and within uint32 range
        // to avoid extremely large jumps; still wide enough to find both parities
        uint256 timestamp = bound(ts, 1, type(uint32).max);

        // set block.timestamp and a fixed block.difficulty to make randomness deterministic
        vm.warp(timestamp);
        vm.roll(1); // advance block number slightly
        // pick a fixed difficulty so only timestamp varies; difficulty can be any non-zero
        // value — keep it wide but constant for test determinism
        vm.tick(0);
        // ensure we call from an EOA that has funds
        address player = address(0xABCD);
        vm.deal(player, 100 ether);

        // prepare to call play() with exact ticket amount
        uint256 ticket = 10; // matches C.TICKET_AMOUNT constant
        vm.prank(player);
        c.play{value: ticket}();

        // compute the expected parity used by the reference contract
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;

        // General rule (single assertion): after play(), pot == 0 iff random == 0
        // (reference contract resets pot on random==0; mutant resets on random==1)
        if (random == 0) {
            // reference: payout occurred -> pot == 0
            assertTrue(c.pot() == 0);
        } else {
            // reference: no payout -> pot == ticket (since pot started 0 and we added ticket)
            assertTrue(c.pot() == ticket);
        }
    }
}

