        // We assert that pot == 0. This holds for the reference implementation for any admissible run and will be violated by the mutant for some fuzzed scenarios.
        assertTrue(c.pot() == 0);
    }
}

// Attacker contract: repeatedly calls play until it observes pot reset or until it triggers the vulnerable path.
// It reverts on receiving Ether to model a malicious/bug-triggering recipient that can cause differing behavior when player is paid before bank.
contract Attacker {
    C target;
    uint attempts;

    constructor(address _target) payable {
        target = C(_target);
    }

    // perform a single play call; we will call this from the test with value
    function doPlay() public payable {
        // call play once; if the player's payout occurs and the mutated contract pays player first,
        // this receive() revert will cause different outcome. We just invoke play once here.
        // forward the exact msg.value
        target.play{value: msg.value}();
    }

    // revert on receiving funds to emulate a failing recipient/fallback
    receive() external payable {
        revert("I refuse funds");
    }
}

