pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: seed to influence which branch and the adversary's behavior
    function testFuzz_property(uint256 seed) public {
        // Keep seed wide but nonzero to allow randomness in helper behavior
        vm.assume(seed != 0);

        // Deploy an adversarial player whose receive will revert to simulate a failing player
        // that causes the difference when player is paid before bank in the mutant.
        AdversarialPlayer adv = new AdversarialPlayer(seed % 2 == 0);

        // Fund adversarial player so it can call play()
        vm.deal(address(adv), 100 ether);

        // The contract expects exactly 10 wei (TICKET_AMOUNT) per play; use that exact value
        uint256 ticket = 10;

        // Make the adversarial player call play(); we use prank so msg.sender is adv
        vm.prank(address(adv));
        // call play with exact ticket amount
        try adv.callPlay{value: ticket}(address(c)) {
            // no-op
        } catch {
            // ignore revert from the external interaction; we'll observe pot via getter
        }

        // General rule to assert on C: after play() returns (regardless of reverts), the reference
        // implementation always ensures pot == 0 (when the winning branch executed). We assert pot == 0.
        // This holds for the reference contract for all admissible inputs; the mutant that pays
        // the player first can leave pot != 0 when the player's receive reverts.
        assertTrue(c.pot() == 0);
    }
}

// Adversarial helper that can either revert on receive or accept funds.
contract AdversarialPlayer {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }

    // call play on target contract
    function callPlay(address target) external payable {
        C(target).play{value: msg.value}();
    }

    // receive will revert when shouldRevert == true to simulate a hostile payable recipient
    receive() external payable {
        if (shouldRevert) revert("bad player");
    }
}
